const http = require('http');
const url = require('url');
const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;
const clients = [];
const messages = [];
function sendEvent(client, data) {
  client.write(`data: ${JSON.stringify(data)}\n\n`);
}
function broadcast(data) {
  for (const c of clients) {
    sendEvent(c, data);
  }
}
function serveIndex(res) {
  const html = `<!doctype html><html><head><meta charset=\

>发送</button>
<script>
const log = document.getElementById('log');
const es = new EventSource('/events');
es.onmessage = (e) => { const data = JSON.parse(e.data); const p = document.createElement('div'); p.textContent = '[' + data.time + '] ' + data.text; log.appendChild(p); log.scrollTop = log.scrollHeight; };
function send(){ const v = document.getElementById('msg').value; fetch('/message',{ method:'POST', headers:{'Content-Type':'text/plain'}, body:v }); document.getElementById('msg').value=''; }
</script>
</body></html>`;
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(html);
}
const server = http.createServer((req, res) => {
  const parsed = url.parse(req.url, true);
  if (parsed.pathname === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok', port: PORT }));
    return;
  }
  if (parsed.pathname === '/') {
    serveIndex(res);
    return;
  }
  if (parsed.pathname === '/events') {
    res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control':'no-cache', 'Connection':'keep-alive' });
    res.write(':ok\n\n');
    clients.push(res);
    for (const m of messages) sendEvent(res, m);
    req.on('close', () => { const i = clients.indexOf(res); if (i >= 0) clients.splice(i,1); });
    return;
  }
  if (parsed.pathname === '/message' && req.method === 'POST') {
    let body = '';
    req.on('data', chunk => body += chunk.toString());
    req.on('end', () => {
      const msg = { text: body || '{{message}}', time: new Date().toISOString() };
      messages.push(msg);
      broadcast(msg);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ ok: true }));
    });
    return;
  }
  res.writeHead(404, { 'Content-Type':'application/json' });
  res.end(JSON.stringify({ error: 'not found' }));
});
server.listen(PORT, () => { console.log('chat server on ' + PORT); });
